<section id="kpis">
  <h2>Executive KPI Summary</h2>
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-label">Average HSC Result</div>
      <div class="kpi-value">{kpi_data['avg_hsc']:.2f}</div>
